import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Table, Badge, Alert, ProgressBar } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { userAPI } from '../../services/api';
import { getUser } from '../../utils/auth';

const UserDashboard = () => {
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0
  });
  const [recentBookings, setRecentBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const user = getUser();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching user dashboard data...');
      const response = await userAPI.getMyBookings();
      console.log('📊 User dashboard API response:', response);
      
      // Handle nested response structure
      let bookings = response.data;
      if (response.data && response.data.data) {
        bookings = response.data.data;
      }
      
      console.log('📋 Bookings data:', bookings);
      
      // Ensure bookings is an array
      if (!Array.isArray(bookings)) {
        console.warn('⚠️ Bookings is not an array, setting to empty array');
        bookings = [];
      }

      // Calculate stats
      const stats = {
        total: bookings.length,
        pending: bookings.filter(b => b.status === 'pending').length,
        approved: bookings.filter(b => b.status === 'approved').length,
        rejected: bookings.filter(b => b.status === 'rejected').length
      };

      setStats(stats);
      setRecentBookings(bookings.slice(0, 5)); // Show last 5 bookings
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      toast.error('Gagal memuat data dashboard');
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger'
    };
    const text = {
      pending: 'Menunggu',
      approved: 'Disetujui',
      rejected: 'Ditolak'
    };
    return <Badge bg={variants[status]} className="px-3 py-2">{text[status]}</Badge>;
  };

  const getRequestTypeIcon = (type) => {
    switch (type) {
      case 'room': return 'fas fa-door-open text-primary';
      case 'zoom': return 'fas fa-video text-info';
      default: return 'fas fa-calendar-alt text-secondary';
    }
  };

  const getSuccessRate = () => {
    if (stats.total === 0) return 0;
    return Math.round((stats.approved / stats.total) * 100);
  };

  if (loading) {
    return (
      <div className="d-flex justify-content-center align-items-center" style={{ minHeight: '60vh' }}>
        <div className="text-center">
          <div className="spinner-border text-primary mb-3" style={{ width: '3rem', height: '3rem' }}>
            <span className="visually-hidden">Loading...</span>
          </div>
          <p className="text-muted">Memuat dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <Container fluid className="py-4">
      {/* Welcome Header */}
      <Row className="mb-5">
        <Col>
          <div className="fade-in-up">
            <div className="d-flex align-items-center mb-3">
              <div className="bg-gradient-primary rounded-circle d-flex align-items-center justify-content-center me-3" style={{ width: '60px', height: '60px' }}>
                <i className="fas fa-user text-white fs-4"></i>
              </div>
              <div>
                <h1 className="text-gradient mb-1">Dashboard User</h1>
                <p className="text-muted mb-0 fs-5">
                  <i className="fas fa-hand-wave me-2 text-warning"></i>
                  Selamat datang kembali, <strong>{user?.name || user?.email}!</strong>
                </p>
              </div>
            </div>
            
            {stats.total > 0 && (
              <Alert variant="info" className="d-flex align-items-center">
                <i className="fas fa-chart-line me-2"></i>
                <div className="flex-grow-1">
                  <strong>Tingkat Persetujuan: {getSuccessRate()}%</strong>
                  <div className="mt-2">
                    <ProgressBar 
                      now={getSuccessRate()} 
                      variant={getSuccessRate() >= 70 ? 'success' : getSuccessRate() >= 40 ? 'warning' : 'danger'}
                      style={{ height: '8px' }}
                    />
                  </div>
                </div>
              </Alert>
            )}
          </div>
        </Col>
        <Col xs="auto" className="d-flex align-items-start">
          <div className="fade-in-right">
            <Button as={Link} to="/user/booking" variant="primary" size="lg" className="shadow-soft">
              <i className="fas fa-plus me-2"></i>
              Buat Booking Baru
            </Button>
          </div>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-5 g-4">
        <Col md={6} lg={3}>
          <Card className="stats-card bg-gradient-primary text-white fade-in-up" style={{ animationDelay: '0.1s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-calendar-alt fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.total}</h2>
              <p className="mb-0 opacity-90">Total Booking</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6} lg={3}>
          <Card className="stats-card bg-warning text-white fade-in-up" style={{ animationDelay: '0.2s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-clock fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.pending}</h2>
              <p className="mb-0 opacity-90">Menunggu Persetujuan</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6} lg={3}>
          <Card className="stats-card bg-success text-white fade-in-up" style={{ animationDelay: '0.3s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-check-circle fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.approved}</h2>
              <p className="mb-0 opacity-90">Disetujui</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={6} lg={3}>
          <Card className="stats-card bg-danger text-white fade-in-up" style={{ animationDelay: '0.4s' }}>
            <Card.Body className="text-center">
              <i className="fas fa-times-circle fa-3x mb-3"></i>
              <h2 className="fw-bold">{stats.rejected}</h2>
              <p className="mb-0 opacity-90">Ditolak</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Recent Bookings */}
      <Row>
        <Col>
          <Card className="fade-in-up" style={{ animationDelay: '0.5s' }}>
            <Card.Header className="d-flex justify-content-between align-items-center">
              <div className="d-flex align-items-center">
                <i className="fas fa-history me-2 text-primary"></i>
                <h4 className="mb-0 fw-bold">Booking Terbaru</h4>
              </div>
              <Button as={Link} to="/user/mybookings" variant="outline-primary" className="d-flex align-items-center">
                <span className="me-2">Lihat Semua</span>
                <i className="fas fa-arrow-right"></i>
              </Button>
            </Card.Header>
            <Card.Body className="p-0">
              {recentBookings.length > 0 ? (
                <div className="table-responsive">
                  <Table className="mb-0" hover>
                    <thead>
                      <tr>
                        <th className="border-0 fw-bold">Booking Details</th>
                        <th className="border-0 fw-bold">Tanggal & Waktu</th>
                        <th className="border-0 fw-bold">Jenis</th>
                        <th className="border-0 fw-bold">Status</th>
                        <th className="border-0 fw-bold">Aksi</th>
                      </tr>
                    </thead>
                    <tbody>
                      {recentBookings.map((booking, index) => (
                        <tr key={booking.id} className="fade-in-up" style={{ animationDelay: `${0.6 + index * 0.1}s` }}>
                          <td>
                            <div>
                              <div className="fw-bold text-dark">{booking.title}</div>
                              <small className="text-muted">
                                <i className="fas fa-users me-1"></i>
                                {booking.participants || 'N/A'} peserta
                              </small>
                            </div>
                          </td>
                          <td>
                            <div>
                              <div className="fw-medium">
                                <i className="fas fa-calendar me-1 text-primary"></i>
                                {new Date(booking.date).toLocaleDateString('id-ID', {
                                  weekday: 'short',
                                  year: 'numeric',
                                  month: 'short',
                                  day: 'numeric'
                                })}
                              </div>
                              <small className="text-muted">
                                <i className="fas fa-clock me-1"></i>
                                {booking.start_time} - {booking.end_time}
                              </small>
                            </div>
                          </td>
                          <td>
                            <div className="d-flex align-items-center">
                              <i className={`${getRequestTypeIcon(booking.request_type)} me-2`}></i>
                              <Badge bg="info" className="text-uppercase">
                                {booking.request_type}
                              </Badge>
                            </div>
                          </td>
                          <td>{getStatusBadge(booking.status)}</td>
                          <td>
                            <Button 
                              as={Link} 
                              to={`/user/mybookings`} 
                              variant="outline-primary" 
                              size="sm"
                              className="d-flex align-items-center"
                            >
                              <i className="fas fa-eye me-1"></i>
                              Detail
                            </Button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </Table>
                </div>
              ) : (
                <div className="text-center py-5">
                  <div className="mb-4">
                    <i className="fas fa-calendar-times text-muted" style={{ fontSize: '4rem' }}></i>
                  </div>
                  <h5 className="text-muted mb-3">Belum Ada Booking</h5>
                  <p className="text-muted mb-4">
                    Mulai dengan membuat booking pertama Anda untuk ruangan atau meeting online.
                  </p>
                  <Button as={Link} to="/user/booking" variant="primary" size="lg" className="px-4">
                    <i className="fas fa-plus me-2"></i>
                    Buat Booking Pertama
                  </Button>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Quick Actions */}
      <Row className="mt-4">
        <Col>
          <Card className="fade-in-up" style={{ animationDelay: '0.7s' }}>
            <Card.Body>
              <h5 className="fw-bold mb-3">
                <i className="fas fa-bolt text-warning me-2"></i>
                Quick Actions
              </h5>
              <Row className="g-3">
                <Col md={4}>
                  <Button 
                    as={Link} 
                    to="/user/booking" 
                    variant="outline-primary" 
                    className="w-100 h-100 d-flex flex-column align-items-center justify-content-center py-3"
                  >
                    <i className="fas fa-plus-circle fa-2x mb-2"></i>
                    <span className="fw-medium">Booking Baru</span>
                  </Button>
                </Col>
                <Col md={4}>
                  <Button 
                    as={Link} 
                    to="/user/mybookings" 
                    variant="outline-success" 
                    className="w-100 h-100 d-flex flex-column align-items-center justify-content-center py-3"
                  >
                    <i className="fas fa-list-alt fa-2x mb-2"></i>
                    <span className="fw-medium">Riwayat Booking</span>
                  </Button>
                </Col>
                <Col md={4}>
                  <Button 
                    variant="outline-info" 
                    className="w-100 h-100 d-flex flex-column align-items-center justify-content-center py-3"
                  >
                    <i className="fas fa-question-circle fa-2x mb-2"></i>
                    <span className="fw-medium">Bantuan</span>
                  </Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default UserDashboard;
